import { test } from 'node:test';
import assert from 'node:assert/strict';
import { getUserName } from '../src/user.js';
import { greet } from '../src/app.js';

test('getUserName trims the name', () => {
  assert.equal(getUserName({ name: '  Ada ' }), 'Ada');
});

test('greet uses the name', () => {
  assert.equal(greet({ name: 'Ada' }), 'Hello, Ada');
});
